#pragma once#include <vector>#include <map>#include <winbase.h>#include <algorithm>#ifndef NOTIFIER_INTERFACE_ONLY#include <macros/IntrusivePtr.h>#endifstruct INotifier {  struct SINK : public ref_counted  {    virtual int OnNotify(INotifier* pSender, int nCode, void* lpData) = 0;    virtual const type_info& GetType()    {      return typeid(NULL);    }    virtual ~SINK()     {    }  };  typedef TIntrusivePtr<INotifier::SINK> CONNECTION;  virtual bool Advise(SINK* pSink)               = 0;  virtual bool Unadvise(SINK* pSink)             = 0;  virtual void DoNotify(int nCode, void* lpData = NULL) = 0;  template<typename A>  void DoNotify( int nCode, A*lpData )  {    DoNotifyTyped( nCode, lpData );  }  virtual ~INotifier()   {  }protected:  virtual void DoNotifyTyped(int nCode, void* lpData ) = 0;}; template<class T>struct NotifierImpl   : public T  , public ref_counted{    typedef std::vector<INotifier::SINK*> s_vector;    s_vector                              sinks;    CRITICAL_SECTION m_csAccess;    struct TCriticalSectionGuardRs    {      LPCRITICAL_SECTION m_cs;      TCriticalSectionGuardRs( LPCRITICAL_SECTION cs )      : m_cs( cs )      {        EnterCriticalSection( m_cs );      }      ~TCriticalSectionGuardRs()      {        LeaveCriticalSection( m_cs );      }    };    NotifierImpl()    {      InitializeCriticalSection( &m_csAccess );    }    ~NotifierImpl()    {      DeleteCriticalSection( &m_csAccess );    }    virtual bool Advise(INotifier::SINK* pSink)    {      TCriticalSectionGuardRs g(&m_csAccess);      for ( size_t i = 0; i < sinks.size(); ++i )      {        if (sinks[i] == NULL)        {          sinks[i] = pSink;          return true;        }      }      sinks.push_back(pSink);      return true;    }    virtual bool Unadvise(INotifier::SINK* pSink)    {      TCriticalSectionGuardRs g(&m_csAccess);      s_vector::iterator iter = std::find( sinks.begin(), sinks.end(), pSink );      if( iter!=sinks.end() )      {        sinks.erase( iter );        return true;      }      return false;    }    virtual void DoNotify(int nCode = 0, void* lpData = NULL )    {      TCriticalSectionGuardRs g(&m_csAccess);      for( size_t i = 0; i < sinks.size(); ++i )      {        s_vector::value_type vt = sinks[i];        if( vt != NULL)          vt->OnNotify(this, nCode, lpData);      }    }    virtual void DoNotifyTyped(int nCode, void* lpData )    {      TCriticalSectionGuardRs g(&m_csAccess);      for( size_t i = 0; i < sinks.size(); ++i )      {        s_vector::value_type vt = sinks[i];        if( vt != NULL)        {          vt->OnNotify(this, nCode, lpData);        }      }    }    virtual int DoNotifyUntilRetValue(int nRetValue, int nCode = 0, void* lpData = NULL)    {      TCriticalSectionGuardRs g(&m_csAccess);      for ( size_t i = 0; i < sinks.size(); ++i )      {        if(sinks[i] != NULL)          if(sinks[i]->OnNotify(this, nCode, lpData) == nRetValue)            return nRetValue;      }      return 0;    }};///////////////////////////////////////////////////////////////////////////////template< typename T, typename F >class NotifierSinkBase :    public TIntrusivePtrImpl<INotifier::SINK>{protected:    INotifier* m_pNotifier;    T*         m_pClient;    F          m_pFunc;    virtual void PreDelete()    {      Disconnect();    }public:    NotifierSinkBase(T* pClient = NULL, F pFunc = NULL) :        m_pNotifier(NULL),        m_pClient(pClient),        m_pFunc(pFunc)    {    }    virtual ~NotifierSinkBase()    {        Disconnect();    }    void Connect(INotifier* pNotifier)    {      if(m_pNotifier != NULL)        m_pNotifier->Unadvise(this);      m_pNotifier = pNotifier;      if(m_pNotifier != NULL)        m_pNotifier->Advise(this);    }    void Connect(INotifier* pNotifier, T* pClient, F pFunc)    {      m_pClient = pClient;      m_pFunc   = pFunc;      Connect(pNotifier);    }    void Disconnect()    {      Connect(NULL);    }};///////////////////////////////////////////////////////////////////////////////template< typename T >class NotifierSink0_ :    public NotifierSinkBase<T, int (T::*)()>{public:    NotifierSink0_(T* pClient = NULL, int (T::*pFunc)() = NULL) :        NotifierSinkBase<T, int (T::*)()>(pClient, pFunc)    {    }    virtual int OnNotify(INotifier* pSender, int nCode, void* lpData)    {      if (m_pClient && m_pFunc)        return (m_pClient->*m_pFunc)();      return 0;    }};///////////////////////////////////////////////////////////////////////////////template< typename T >class NotifierSink0C_ :  public NotifierSinkBase<T, int (T::*)()>{  int m_code;public:  NotifierSink0C_(T* pClient = NULL, int (T::*pFunc)() = NULL, int code = 0) :      NotifierSinkBase<T, int (T::*)()>(pClient, pFunc),      m_code(code)  {  }  virtual int OnNotify(INotifier* pSender, int nCode, void* lpData)  {    if(m_pClient && m_pFunc && nCode == m_code)    return (m_pClient->*m_pFunc)();    return 0;  }};///////////////////////////////////////////////////////////////////////////////template< typename T >class NotifierSink1_ :  public NotifierSinkBase<T, int (T::*)(int)>{public:  NotifierSink1_(T* pClient = NULL, int (T::*pFunc)(int) = NULL) :    NotifierSinkBase<T, int (T::*)(int)>(pClient, pFunc)  {  }  virtual int OnNotify(INotifier* pSender, int nCode, void* lpData)  {    if(m_pClient && m_pFunc)      return (m_pClient->*m_pFunc)(nCode);    return 0;  }};///////////////////////////////////////////////////////////////////////////////template< typename T >class NotifierSink1C_ :    public NotifierSinkBase<T, int (T::*)(void*)>{    int m_code;public:    NotifierSink1C_(T* pClient = NULL, int (T::*pFunc)(void*) = NULL, int code = 0) :        NotifierSinkBase<T, int (T::*)(void*)>(pClient, pFunc),        m_code(code)    {    }    virtual int OnNotify(INotifier* pSender, int nCode, void* lpData)    {        if (m_pClient && m_pFunc && nCode == m_code)            return (m_pClient->*m_pFunc)(lpData);        return 0;    }};template< typename T, typename A >class NotifierSink1CA_ :  public NotifierSinkBase<T, int (T::*)(A*)>{  int m_code;public:  NotifierSink1CA_(T* pClient = NULL, int (T::*pFunc)(A*) = NULL ) :      NotifierSinkBase<T, int (T::*)(A*)>(pClient, pFunc)        , m_code(0)      {      }      virtual int OnNotify(INotifier* pSender, int nCode, void* lpData)      {        if (m_pClient && m_pFunc )          return (m_pClient->*m_pFunc)( (A*)lpData );        return 0;      }      virtual const type_info& GetType()      {        return typeid(A);      }};///////////////////////////////////////////////////////////////////////////////template< typename T >class NotifierSink2_ :    public NotifierSinkBase<T, int (T::*)(int, void*)>{public:    NotifierSink2_(T* pClient = NULL, int (T::*pFunc)(int, void*) = NULL) :        NotifierSinkBase<T, int (T::*)(int, void*)>(pClient, pFunc)    {    }    virtual int OnNotify(INotifier* pSender, int nCode, void* lpData)    {        if (m_pClient && m_pFunc)            return (m_pClient->*m_pFunc)(nCode, lpData);        return 0;    }};template< typename T, typename A >class NotifierSink2A_ :  public NotifierSinkBase<T, int (T::*)(int, A*)>{public:  NotifierSink2A_(T* pClient = NULL, int (T::*pFunc)(int, A*) = NULL) :      NotifierSinkBase<T, int (T::*)(int, A*)>(pClient, pFunc)      {      }      virtual int OnNotify(INotifier* pSender, int nCode, void* lpData)      {        if (m_pClient && m_pFunc)          return (m_pClient->*m_pFunc)(nCode, (A*)lpData);        return 0;      }      virtual const type_info& GetType()      {        return typeid(A);      }};///////////////////////////////////////////////////////////////////////////////template< typename 